using Cultivation.Domain;
using Cultivation.Simulation;
using Cultivation.Persistence;
internal static class R2BatchIntegrationTests
{
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static WorldState RestWorld(){var w=LifeEventScenario.Create();int n=w.Characters.FindIndex(a=>a.Id=="player");var a=w.Characters[n];w.Characters[n]=a with {Health=80,DemoLocationId="sect",HexPosition=RegionGeometry.Resolve(w.HexMap!,a,"sect"),Stamina=a.Stamina! with {Current=50,HasBed=false}};int b=w.Time!.Budgets.FindIndex(x=>x.ActorId=="player");if(b<0)w.Time.Budgets.Add(new("player",0,28));else w.Time.Budgets[b]=new("player",0,28);return w;}
    public static IEnumerable<(string Name,Action Body)> Cases=>new (string,Action)[]{
        ("R2 free wait tracks duration with zero AP and once completion",()=>{var e=new SimulationEngine(LifeEventScenario.Create());e.AdvanceTo(1020);var w=e.Snapshot();int ap=w.Time!.Budgets.Single(b=>b.ActorId=="player").Remaining;var i=new ActionIntent("batch-wait","player","player","time",1,0,DecisionSource.Player,ActionKind.Wait);e.Submit(i);e.AdvanceTo(1020);w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(a.Phase==ActionPhase.Running&&a.DueAt==1620&&a.ActionPointsPaid==0&&w.Time.Budgets.Single(b=>b.ActorId=="player").Remaining==ap,"Wait state/AP wrong");e.AdvanceTo(1620);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&w.Events.Count(x=>x.ActionId==i.Id&&x.Kind=="WaitCompleted")==1&&w.Time.Budgets.Single(b=>b.ActorId=="player").Remaining==ap,"Wait completion wrong");}),
        ("R2 rest tracks pulses through JSON SQLite and finishes once",()=>{var e=new SimulationEngine(RestWorld());e.AdvanceTo(1020);var i=new ActionIntent("batch-rest","player","player","stamina",1,0,DecisionSource.Player,ActionKind.Rest);e.Submit(i);e.AdvanceTo(1020);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(a.Phase==ActionPhase.Running&&a.DueAt==1620&&a.ActionPointsPaid==0,"Rest action missing");e.AdvanceTo(1620);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Running&&w.Time.ActionRuntime.Actions[i.Id].DueAt==2220,"Rest second pulse not tracked");string dir=Path.Combine(Path.GetTempPath(),"r2-batch-rest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{foreach(IWorldStore store in new IWorldStore[]{new JsonWorldStore(),new SqliteWorldStore()}){string p=Path.Combine(dir,store.GetType().Name);store.Save(p,w);var x=new SimulationEngine(w);var y=new SimulationEngine(store.Load(p));x.AdvanceTo(2220);y.AdvanceTo(2220);var done=y.Snapshot();Check(WorldCodec.Digest(x.Snapshot())==WorldCodec.Digest(done)&&done.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&done.Characters.Single(c=>c.Id=="player").Health==100,"Rest continuation differs");}}finally{foreach(string p in Directory.GetFiles(dir))File.Delete(p);Directory.Delete(dir);}}),
        ("R2 social deferred command starts and completes without duplicate",()=>{var e=new SimulationEngine(LifeEventScenario.Create());e.AdvanceTo(1020);var i=new ActionIntent("batch-social","npc:00","player","social",1,0,DecisionSource.Npc,ActionKind.InviteCooperation);e.Submit(i);e.AdvanceTo(1020);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(a.Phase==ActionPhase.Running&&!w.SocialOffers.Any(o=>o.Id==i.Id),"Offer made early");e.AdvanceTo(a.DueAt);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&w.SocialOffers.Count(o=>o.Id==i.Id)==1,"Offer did not complete");}),
        ("R2 dungeon deferred exploration completes before battle freezes time",()=>{var w=LifeEventScenario.Create();int n=w.Characters.FindIndex(c=>c.Id=="player");var actor=w.Characters[n];w.Characters[n]=actor with {DemoLocationId="dungeon",HexPosition=RegionGeometry.Resolve(w.HexMap!,actor,"dungeon"),Health=100};w.Dungeon=w.Dungeon! with {EncounterChance=1};var e=new SimulationEngine(w);e.AdvanceTo(1020);var i=new ActionIntent("batch-dungeon","player","dungeon","combat",1,0,DecisionSource.Player,ActionKind.ExploreDungeon);e.Submit(i);e.AdvanceTo(1020);w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(a.Phase==ActionPhase.Running&&w.BoardBattle is null,"Encounter began early");e.AdvanceTo(a.DueAt);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&w.BoardBattle is {Phase:BoardBattlePhase.Active}&&e.WorldTimeSeconds==a.DueAt,"Encounter lifecycle or freeze failed");})
    };
}
